package com.yeyamo_mobile.api.recommendation_service.domain;import static org.junit.jupiter.api.Assertions.*;import java.time.Instant;import org.junit.jupiter.api.Test;
class RecommendationDomainTest{@Test void rejectsPartialCoordinates(){assertThrows(IllegalArgumentException.class,()->new RecommendationContext(4d,null));}@Test void rejectsInvalidCandidateCoordinates(){assertThrows(IllegalArgumentException.class,()->candidate(91d,9d));}@Test void normalizesNegativePopularity(){assertEquals(0,candidate(4d,9d).popularity());}private Candidate candidate(Double lat,Double lng){return new Candidate("catalog:1","1",CandidateKind.PLACE,"Place",null,null,lat,lng,-5,true,Instant.now(),Instant.now());}}
